	"strings"
)

func DecodeTrail(encoded string) ([]string, error) {
	if !strings.HasPrefix(encoded, "/") || len(encoded) == 1 {
		return nil, fmt.Errorf("invalid trail")
	}

	raw := strings.Split(encoded[1:], "/")
